    'reaction-time': [["अच्छा रिएक्शन टाइम कितना होता है?","ज़्यादातर लोग देखी हुई चीज़ पर लगभग 250 से 300 मिलीसेकंड में प्रतिक्रिया करते हैं। 200 ms से कम बहुत तेज़ है।"],["क्या ऑनलाइन खेलना निष्पक्ष है?","हाँ। हर फ़ोन अपने खिलाड़ी का समय उसी स्क्रीन पर हरा दिखने से नापता है, इसलिए नेटवर्क की देरी किसी का समय नहीं बदलती।"]],
