  'bingo': [["বন্ধুরা কি আমার কার্ড দেখতে পায়?","না। প্রতিটা ফোন শুধু নিজের কার্ড পায়; বাকিগুলো খেলা শেষ না হওয়া পর্যন্ত লুকোনো থাকে।"],["আগে বলা নম্বর টাইপ করলে কী হবে?","কিছু হারাবে না: খেলাটা জানিয়ে দেবে, আর সময় শেষ হওয়ার আগে তুমি অন্য নম্বর টাইপ করতে পারবে।"]],
  'unblock-puzzle': [["সব পার্কিং কি সমাধান করা যায়?","হ্যাঁ। প্রতিটা পার্কিং যোগ করার আগে কম্পিউটার সমাধান করেছে, আর সবচেয়ে কম চাল তোমার চালের সংখ্যার উপরে দেখায়।"],["এক চাল কাকে বলে?","একটা গাড়ি সরানো, যত দূরই যাক, এক চাল।"]],
  'hoop-flick': [['এটা কি শেষ হয়?', 'না। নিশানা না ফসকানো পর্যন্ত হুপ আসতেই থাকে।'], ['দুজন কি খেলতে পারে?', 'হ্যাঁ, এক স্ক্রিনে, কাছে বা অনলাইনে। প্রত্যেকের কোর্টের নিজের অর্ধেক থাকে।']],
  'ghost-hostel': [['একটা খেলা কতক্ষণের?', 'এক রাত: আড়াই মিনিট।'], ['আমি কি বন্ধুদের সঙ্গে খেলতে পারি?', 'হ্যাঁ, চারজন পর্যন্ত, প্রত্যেকে নিজের ঘরে। খালি ঘর কম্পিউটার খেলোয়াড় নেয়।']],
